def _unpacked(text: str, dtype: str, count: int) -> np.ndarray:
    raw = zlib.decompress(base64.b85decode(text))
    planes = np.frombuffer(raw, dtype=np.uint8).reshape(np.dtype(dtype).itemsize, -1)
    values = np.ascontiguousarray(planes.T).view(dtype).ravel()
    if values.size != count:
        raise RuntimeError("the D3 tables are damaged")
    return values


@functools.cache
def reference_c6() -> np.ndarray:
    """(57811,) float64 C6 in Hartree bohr^6 of the pairs of references, in
    the order of _C6."""
    values = _unpacked(_C6, "<u4", 57811).astype(np.float64) / 1e4
    values.flags.writeable = False
    return values


@functools.cache
def vdw_radii() -> np.ndarray:
    """(103, 103) float64 R0 of each pair of elements in Å."""
    packed = _unpacked(_R0, "<u2", 5356).astype(np.float64) / 1e4
    table = np.zeros((MAX_Z, MAX_Z))
    i, j = np.tril_indices(MAX_Z)
    table[i, j] = packed
    table[j, i] = packed
    table.flags.writeable = False
    return table
